@cuda.jit(device=True)

def gap_of_k(ptp, pt_radius, k, plane_y):

    h = k - (k % 2)

    gh = ptp[h * 3 + 1] + pt_radius[h] - plane_y

    gm = ptp[(h + 1) * 3 + 1] + pt_radius[h + 1] - plane_y

    if gh < gm:

        return gh

    return gm





@cuda.jit(device=True)

def row_dot(row, x):

    s = float(0.0)

    for i in range(18):

        s = s + row[i] * x[i]

    return s





@cuda.jit(device=True)

def mat_vec(inv, row, out):

    # out = inv * row

    for i in range(18):

        s = float(0.0)

        for j in range(18):

            s = s + inv[i * 18 + j] * row[j]

        out[i] = s





@cuda.jit(device=True)

def rows_row(rows, k, out):

    for i in range(18):

        out[i] = rows[k * 18 + i]





@cuda.jit(device=True)

def gram_factor10(g, k, rhs, lam):

    scale = float(0.0)

    for i in range(k):

        d = g[i * k + i]

        if d < float(0.0):

            d = -d

        if d > scale:

            scale = d

    if not (scale > float(0.0)):

        return 0

    for i in range(k):

        for j in range(i):

            avg = (g[i * k + j] + g[j * k + i]) * float(0.5)

            g[i * k + j] = avg

            g[j * k + i] = avg

    l = cuda.local.array(100, dtype=float64)
    for _zzero11 in range(100):
        l[_zzero11] = 0.0

    for i in range(k):

        for j in range(i + 1):

            t = g[i * k + j]

            for m in range(j):

                t = t - l[i * k + m] * l[j * k + m]

            if i == j:

                if not (t > float(1e-9) * scale):

                    return 0

                l[i * k + j] = math.sqrt(t)

            else:

                l[i * k + j] = t / l[j * k + j]

    for i in range(k):

        lam[i] = float(0.0)

    for col in range(k):

        y = cuda.local.array(10, dtype=float64)
        for _zzero12 in range(10):
            y[_zzero12] = 0.0

        x = cuda.local.array(10, dtype=float64)
        for _zzero13 in range(10):
            x[_zzero13] = 0.0

        for i in range(k):

            t = float(0.0)

            if col == i:

                t = float(1.0)

            for m in range(i):

                t = t - l[i * k + m] * y[m]

            y[i] = t / l[i * k + i]

        ii = k - 1

        while ii >= 0:

            t = y[ii]

            for m in range(ii + 1, k):

                t = t - l[m * k + ii] * x[m]

            x[ii] = t / l[ii * k + ii]

            lam[ii] = lam[ii] + x[ii] * rhs[col]

            ii = ii - 1

    return 1





@cuda.jit(device=True)

def project_rows(initial, inv, rows, floors, R, n_stops, p_out, multipliers):

    # Mass-metric active-set projection (the free-root D6 law, lifted

    # row-count-only): the deterministic full subset enumeration, the

    # stop-holding tier first. Returns 1 with p_out, or 0 = gait_row_budget.

    if R < 1 or R > 10:

        return 0

    tier = int32(0)

    while tier <= 1:

        mask = int32(0)

        while mask < (1 << R):

            skip = int32(0)

            if mask != 0:

                holds = int32(1)

                for k in range(n_stops):

                    if not ((mask >> k) & 1):

                        holds = 0

                if holds != int32(tier == 0):

                    skip = 1

            else:

                if tier != 0:

                    skip = 1

            if skip == 0:

                act = cuda.local.array(10, dtype=int32)
                for _zzero14 in range(10):
                    act[_zzero14] = 0

                cnt = int32(0)

                for k in range(R):

                    if (mask >> k) & 1:

                        act[cnt] = k

                        cnt = cnt + 1

                legal = int32(1)

                if cnt > 18:

                    legal = 0

                if legal == 1:

                    if cnt == 0:

                        allok = int32(1)

                        rk = cuda.local.array(18, dtype=float64)
                        for _zzero15 in range(18):
                            rk[_zzero15] = 0.0

                        for k in range(R):

                            rows_row(rows, k, rk)

                            tol = float(1e-9) * (float(1.0) + abs(floors[k]))

                            if row_dot(rk, initial) < floors[k] - tol:

                                allok = 0

                        if allok == 1:

                            for i in range(18):

                                p_out[i] = float(0.0)

                            for k in range(R):

                                multipliers[k] = float(0.0)

                            return 1

                    else:

                        gram = cuda.local.array(100, dtype=float64)
                        for _zzero16 in range(100):
                            gram[_zzero16] = 0.0

                        rhs = cuda.local.array(10, dtype=float64)
                        for _zzero17 in range(10):
                            rhs[_zzero17] = 0.0

                        ra = cuda.local.array(18, dtype=float64)
                        for _zzero18 in range(18):
                            ra[_zzero18] = 0.0

                        rb = cuda.local.array(18, dtype=float64)
                        for _zzero19 in range(18):
                            rb[_zzero19] = 0.0

                        ia = cuda.local.array(18, dtype=float64)
                        for _zzero20 in range(18):
                            ia[_zzero20] = 0.0

                        for a in range(cnt):

                            for b in range(cnt):

                                rows_row(rows, act[a], ra)

                                rows_row(rows, act[b], rb)

                                mat_vec(inv, ra, ia)

                                s = float(0.0)

                                for i in range(18):

                                    s = s + ia[i] * rb[i]

                                gram[a * cnt + b] = s

                            rows_row(rows, act[a], ra)

                            rhs[a] = floors[act[a]] - row_dot(ra, initial)

                        lam = cuda.local.array(10, dtype=float64)
                        for _zzero21 in range(10):
                            lam[_zzero21] = 0.0

                        if gram_factor10(gram, cnt, rhs, lam) == 1:

                            valid = int32(1)

                            for k in range(cnt):

                                if lam[k] < float(-1e-10):

                                    valid = 0

                            if valid == 1:

                                for i in range(18):

                                    p_out[i] = float(0.0)

                                for k in range(cnt):

                                    l = lam[k]

                                    if l < float(0.0):

                                        l = float(0.0)

                                    rk = cuda.local.array(18, dtype=float64)
                                    for _zzero22 in range(18):
                                        rk[_zzero22] = 0.0

                                    rows_row(rows, act[k], rk)

                                    for i in range(18):

                                        p_out[i] = p_out[i] + l * rk[i]

                                chg = cuda.local.array(18, dtype=float64)
                                for _zzero23 in range(18):
                                    chg[_zzero23] = 0.0

                                mat_vec(inv, p_out, chg)

                                rk = cuda.local.array(18, dtype=float64)
                                for _zzero24 in range(18):
                                    rk[_zzero24] = 0.0

                                for k in range(R):

                                    tol = float(1e-9) * (float(1.0) + abs(floors[k]))

                                    rows_row(rows, k, rk)

                                    got = row_dot(rk, initial) + row_dot(rk, chg)

                                    if got < floors[k] - tol:

                                        valid = 0

                                if valid == 1:

                                    for k in range(R):

                                        multipliers[k] = float(0.0)

                                    for k in range(cnt):

                                        l = lam[k]

                                        if l < float(0.0):

                                            l = float(0.0)

                                        multipliers[act[k]] = l

                                    return 1

            mask = mask + 1

        tier = tier + 1

    return 0





@cuda.jit(device=True)

def friction_solve(initial, inv, row_n, row_t, floor_n, floor_t, mu, slip_sign, force, ln, lt, mode):

    # gait_controller friction_solve verbatim; mode: 0 none, 1 cone, 2 slide,

    # -1 = the gait_friction_slide_singular swallow

    for i in range(18):

        force[i] = float(0.0)

    ln[0] = float(0.0)

    lt[0] = float(0.0)

    mode[0] = 0

    rn_v = cuda.local.array(18, dtype=float64)
    for _zzero25 in range(18):
        rn_v[_zzero25] = 0.0

    mat_vec(inv, row_n, rn_v)

    rt_v = cuda.local.array(18, dtype=float64)
    for _zzero26 in range(18):
        rt_v[_zzero26] = 0.0

    mat_vec(inv, row_t, rt_v)

    A = row_dot(row_n, rn_v)

    B = row_dot(row_n, rt_v)

    C = row_dot(row_t, rt_v)

    rn = -(row_dot(row_n, initial) - floor_n)

    rt = -(row_dot(row_t, initial) - floor_t)

    det = A * C - B * B

    if det > float(1e-18):

        nn = (rn * C - rt * B) / det

        t = (rt * A - rn * B) / det

        at = t

        if at < float(0.0):

            at = -at

        if nn >= float(0.0) and at <= mu * nn + float(1e-12) and (slip_sign == 0 or t * float(slip_sign) <= float(0.0)):

            for i in range(18):

                force[i] = row_n[i] * nn + row_t[i] * t

            ln[0] = nn

            lt[0] = t

            mode[0] = 1

            return

    s = float(0.0)

    if slip_sign != 0:

        s = float(slip_sign)

    else:

        if rt >= float(0.0):

            s = float(-1.0)

        else:

            s = float(1.0)

    den = A - s * mu * B

    if den <= float(1e-12):

        mode[0] = -1

        return

    nn = rn / den

    t = -s * mu * nn

    if nn >= float(0.0):

        for i in range(18):

            force[i] = row_n[i] * nn + row_t[i] * t

        ln[0] = nn

        lt[0] = t

        mode[0] = 2

        return

    ln[0] = float(0.0)

    lt[0] = float(0.0)

    mode[0] = 0













@cuda.jit(device=True, inline='never')
def rate(q, v, tau, live, plane, mdl, cst, M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, rq, rv, mdi, csti):
    pt_radius_g = mdl[OF_pt_radius:OF_pt_radius + 8]

    pot = fk_eval(q,  v, mdl, mdi, cst,

                  M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias)

    if inverse_spd18(M, inv) == 0:

        return 8

    for i in range(18):

        free[i] = gv[i] - bv[i]

        rq[i] = float(0.0)

    for d in range(12):

        c = mdi[OI_drive_coord + d]

        free[c] = free[c] + (tau[c] - mdl[OF_drive_damping + d] * v[c])

    free_acc = cuda.local.array(18, dtype=float64)
    mat_vec(inv, free, free_acc)
    for i in range(18):
        free[i] = free_acc[i]

    rows = cuda.local.array(180, dtype=float64)
    for _zzero27 in range(180):
        rows[_zzero27] = 0.0

    floors = cuda.local.array(10, dtype=float64)
    for _zzero28 in range(10):
        floors[_zzero28] = 0.0

    R = int32(0)

    n_stops = int32(0)

    stop = int32(0)

    jn = cuda.local.array(18, dtype=float64)
    for _zzero29 in range(18):
        jn[_zzero29] = 0.0

    for d in range(12):

        c = mdi[OI_drive_coord + d]

        jn[c] = float(0.0)

        if abs(q[c] - mdl[OF_lower + c]) < float(1e-10):

            jn[c] = float(1.0)

        elif abs(q[c] - mdl[OF_upper + c]) < float(1e-10):

            jn[c] = float(-1.0)

    speed_scale = float(0.0)

    for d in range(12):

        speed_scale = speed_scale + abs(v[mdi[OI_drive_coord + d]])

    gate = float(1e-6) + float(1e-3) * speed_scale

    for d in range(12):

        c = mdi[OI_drive_coord + d]

        if jn[c] != float(0.0) and abs(v[c]) <= float(1e-9):

            if R >= 10:

                return 5

            for i in range(18):

                rows[R * 18 + i] = float(0.0)

            rows[R * 18 + c] = jn[c]

            floors[R] = float(0.0)

            R = R + 1

            n_stops = n_stops + 1

            stop = 1

    touching = cuda.local.array(4, dtype=int32)
    for _zzero30 in range(4):
        touching[_zzero30] = 0

    mode_k = cuda.local.array(4, dtype=int32)
    for _zzero31 in range(4):
        mode_k[_zzero31] = 0

    rn = cuda.local.array(18, dtype=float64)
    for _zzero32 in range(18):
        rn[_zzero32] = 0.0

    for r in range(4):

        for i in range(18):

            rn[i] = ptJ[(r * 3 + 1) * 18 + i]

        g = gap_of_k(ptp, pt_radius_g, r * 2, cst[CF_plane_y])

        touching[r] = 0

        if plane[r] != 0:

            touching[r] = 1

        elif live[r] != 0 and g <= cst[CF_k_touch] and row_dot(rn, v) <= gate:

            touching[r] = 1

    if csti[CI_contact] != 0 and cst[CF_mu] > float(0.0) and stop == 0:

        jt1 = cuda.local.array(18, dtype=float64)
        for _zzero33 in range(18):
            jt1[_zzero33] = 0.0

        jt2 = cuda.local.array(18, dtype=float64)
        for _zzero34 in range(18):
            jt2[_zzero34] = 0.0

        row_t = cuda.local.array(18, dtype=float64)
        for _zzero35 in range(18):
            row_t[_zzero35] = 0.0

        force = cuda.local.array(18, dtype=float64)
        for _zzero36 in range(18):
            force[_zzero36] = 0.0

        corr = cuda.local.array(18, dtype=float64)
        for _zzero37 in range(18):
            corr[_zzero37] = 0.0

        ln = cuda.local.array(1, dtype=float64)
        for _zzero38 in range(1):
            ln[_zzero38] = 0.0

        lt = cuda.local.array(1, dtype=float64)
        for _zzero39 in range(1):
            lt[_zzero39] = 0.0

        md = cuda.local.array(1, dtype=int32)
        for _zzero40 in range(1):
            md[_zzero40] = 0

        for r in range(4):

            if touching[r] == 0:

                continue

            for i in range(18):

                jt1[i] = ptJ[(r * 3 + 0) * 18 + i]

                jt2[i] = ptJ[(r * 3 + 2) * 18 + i]

            bx = ptbias[r * 3]

            by = ptbias[r * 3 + 1]

            bz = ptbias[r * 3 + 2]

            svx = row_dot(jt1, v)

            svz = row_dot(jt2, v)

            planar = math.hypot(svx, svz)

            dir_x = float(0.0)

            dir_z = float(0.0)

            slip_sign = int32(0)

            if planar > cst[CF_k_slip]:

                dir_x = svx / planar

                dir_z = svz / planar

                slip_sign = 1

            else:

                d1 = bx

                d2 = bz

                for i in range(18):

                    d1 = d1 + jt1[i] * free[i]

                    d2 = d2 + jt2[i] * free[i]

                accel = math.hypot(d1, d2)  # C++ std::hypot(d1, d2)

                if accel > float(1e-9):

                    dir_x = d1 / accel

                    dir_z = d2 / accel

                    slip_sign = 1

            if dir_x == float(0.0) and dir_z == float(0.0):

                continue

            for i in range(18):

                row_t[i] = dir_x * jt1[i] + dir_z * jt2[i]

            # C++ solves against rown[k] -- the CURRENT point's normal row, kept

            # per-point in its touching loop. The port's rn is one scratch left at

            # the LAST point of the touching loop (here point 3's row), so every

            # solve but the last used a foreign row: measured at the tick-3

            # depth-1 half-step, point 2's solve read B=15.59/rn=8.863 (point-3

            # row) where the reference reads B=0.29/rn=8.863 -- a different

            # friction cone and correction. This path is dead until the first

            # fore-pad touch (the hind gaps ride above kTouch), which is why it

            # survived the tick 0..3 census bit-exactly.

            for i in range(18):

                rn[i] = ptJ[(r * 3 + 1) * 18 + i]

            friction_solve(free, inv, rn, row_t, -by, -(dir_x * bx + dir_z * bz), cst[CF_mu], slip_sign,

                           force, ln, lt, md)

            if md[0] > 0:

                mat_vec(inv, force, corr)

                for i in range(18):

                    free[i] = free[i] + corr[i]

                mode_k[r] = md[0]

    for r in range(4):

        if touching[r] == 0:

            continue

        for i in range(18):

            rn[i] = ptJ[(r * 3 + 1) * 18 + i]

        floor_k = -ptbias[r * 3 + 1]

        if mode_k[r] != 0 and row_dot(rn, free) >= floor_k - float(1e-9):

            continue

        if R >= 10:

            return 5

        for i in range(18):

            rows[R * 18 + i] = rn[i]

        floors[R] = floor_k

        R = R + 1

    if R > 0:

        p = cuda.local.array(18, dtype=float64)
        for _zzero41 in range(18):
            p[_zzero41] = 0.0

        mult = cuda.local.array(10, dtype=float64)
        for _zzero42 in range(10):
            mult[_zzero42] = 0.0

        if project_rows(free, inv, rows, floors, R, n_stops, p, mult) == 0:

            return 5

        corr = cuda.local.array(18, dtype=float64)
        for _zzero43 in range(18):
            corr[_zzero43] = 0.0

        mat_vec(inv, p, corr)

        for i in range(18):

            free[i] = free[i] + corr[i]

    for i in range(18):

        rv[i] = free[i]

        rq[i] = v[i]

    return 0





@cuda.jit(device=True, inline='never')

def free_step(q0, v0, w0, tau, live, h, mdl, cst, M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, srq, srv, qa, va, qb, vb, qc, vc, qd, vd, q1, v1, w1, mdi, csti):
    pt_radius_g = mdl[OF_pt_radius:OF_pt_radius + 8]

    rq = cuda.local.array(18, dtype=float64)
    for _zzero44 in range(18):
        rq[_zzero44] = 0.0

    rv = cuda.local.array(18, dtype=float64)
    for _zzero45 in range(18):
        rv[_zzero45] = 0.0

    plane = cuda.local.array(4, dtype=int32)
    for _zzero46 in range(4):
        plane[_zzero46] = 0

    pot = fk_eval(q0,  v0, mdl, mdi, cst,

                  M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias)

    speed_scale = float(0.0)

    for d in range(12):

        speed_scale = speed_scale + abs(v0[mdi[OI_drive_coord + d]])

    gate = float(1e-6) + float(1e-3) * speed_scale

    rn = cuda.local.array(18, dtype=float64)
    for _zzero47 in range(18):
        rn[_zzero47] = 0.0

    for r in range(4):

        for i in range(18):

            rn[i] = ptJ[(r * 3 + 1) * 18 + i]

        g = gap_of_k(ptp, pt_radius_g, r * 2, cst[CF_plane_y])

        if live[r] != 0 and g <= cst[CF_k_touch] and row_dot(rn, v0) <= gate:

            plane[r] = 1

    rc = rate(q0, v0, tau, live, plane, mdl, cst, M, gv, bv, fr, frd, frdd,

              axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, qa, va, mdi, csti)

    if rc != 0:

        return rc

    half = h * float(0.5)

    for i in range(18):

        qb[i] = q0[i] + qa[i] * half

        vb[i] = v0[i] + va[i] * half

    brq = cuda.local.array(18, dtype=float64)
    for _zzero48 in range(18):
        brq[_zzero48] = 0.0

    brv = cuda.local.array(18, dtype=float64)
    for _zzero49 in range(18):
        brv[_zzero49] = 0.0

    rc = rate(qb, vb, tau, live, plane, mdl, cst, M, gv, bv, fr, frd, frdd,

                  axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, brq, brv, mdi, csti)

    if rc != 0:

        return rc

    for i in range(18):

        qc[i] = q0[i] + brq[i] * half

        vc[i] = v0[i] + brv[i] * half

    crq = cuda.local.array(18, dtype=float64)
    for _zzero50 in range(18):
        crq[_zzero50] = 0.0

    crv = cuda.local.array(18, dtype=float64)
    for _zzero51 in range(18):
        crv[_zzero51] = 0.0

    rc = rate(qc, vc, tau, live, plane, mdl, cst, M, gv, bv, fr, frd, frdd,

                  axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, crq, crv, mdi, csti)

    if rc != 0:

        return rc

    for i in range(18):

        qd[i] = q0[i] + crq[i] * h

        vd[i] = v0[i] + crv[i] * h

    drq = cuda.local.array(18, dtype=float64)
    for _zzero52 in range(18):
        drq[_zzero52] = 0.0

    drv = cuda.local.array(18, dtype=float64)
    for _zzero53 in range(18):
        drv[_zzero53] = 0.0

    rc = rate(qd, vd, tau, live, plane, mdl, cst, M, gv, bv, fr, frd, frdd,

                  axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, drq, drv, mdi, csti)

    if rc != 0:

        return rc

    # C++ free_step: end.x[i] += h*(a + 2*b + 2*c + d)/6 — MULTIPLY by h
    # first, THEN divide by 6. The old sixth=h/6 pre-division rounded
    # differently (h/6)*sum != (h*sum)/6 in general.
    for i in range(18):

        q1[i] = q0[i] + h * (qa[i] + float(2.0) * brq[i] + float(2.0) * crq[i] + drq[i]) / float(6.0)

        v1[i] = v0[i] + h * (va[i] + float(2.0) * brv[i] + float(2.0) * crv[i] + drv[i]) / float(6.0)

        w1[i] = w0[i] + tau[i] * (q1[i] - q0[i])

    return 0





@cuda.jit(device=True)

def gram_factor4(g, k, rhs, lam):

    scale = float(0.0)

    for i in range(k):

        d = g[i * k + i]

        if d < float(0.0):

            d = -d

        if d > scale:

            scale = d

    if not (scale > float(0.0)):

        return 0

    # BY-VALUE copy + SYMMETRIZATION (C++ gram_factor: g passed by value,
    # then g[i][j]=g[j][i]=(g[i][j]+g[j][i])/2 for j<i). inner(r_a, inv*r_b)
    # is bitwise asymmetric for a!=b, so this average changes the factor bits.
    gs = cuda.local.array(16, dtype=float64)
    for _zzero54a in range(16):
        gs[_zzero54a] = 0.0
    for _gi in range(k):
        for _gj in range(k):
            gs[_gi * k + _gj] = g[_gi * k + _gj]
    for _gi in range(k):
        for _gj in range(_gi):
            avg = (gs[_gi * k + _gj] + gs[_gj * k + _gi]) / float(2.0)
            gs[_gi * k + _gj] = avg
            gs[_gj * k + _gi] = avg

    l = cuda.local.array(16, dtype=float64)
    for _zzero54 in range(16):
        l[_zzero54] = 0.0

    for i in range(k):

        for j in range(i + 1):

            t = gs[i * k + j]

            for m in range(j):

                t = t - l[i * k + m] * l[j * k + m]

            if i == j:

                if not (t > float(1e-9) * scale):

                    return 0

                l[i * k + j] = math.sqrt(t)

            else:

                l[i * k + j] = t / l[j * k + j]

    for i in range(k):

        lam[i] = float(0.0)

    for col in range(k):

        y = cuda.local.array(4, dtype=float64)
        for _zzero55 in range(4):
            y[_zzero55] = 0.0

        x = cuda.local.array(4, dtype=float64)
        for _zzero56 in range(4):
            x[_zzero56] = 0.0

        for i in range(k):

            t = float(0.0)

            if col == i:

                t = float(1.0)

            for m in range(i):

                t = t - l[i * k + m] * y[m]

            y[i] = t / l[i * k + i]

        ii = k - 1

        while ii >= 0:

            t = y[ii]

            for m in range(ii + 1, k):

                t = t - l[m * k + ii] * x[m]

            x[ii] = t / l[ii * k + ii]

            lam[ii] = lam[ii] + x[ii] * rhs[col]

            ii = ii - 1

    return 1





@cuda.jit(device=True, inline='never')

def impact(q, v, mdl, cst, M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, rc, mdi, csti):
    pt_radius_g = mdl[OF_pt_radius:OF_pt_radius + 8]

    pot = fk_eval(q,  v, mdl, mdi, cst,

                  M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias)

    if inverse_spd18(M, inv) == 0:

        rc[0] = 8

        return float(0.0)

    caught = float(0.0)

    rows = cuda.local.array(180, dtype=float64)
    for _zzero57 in range(180):
        rows[_zzero57] = 0.0

    floors = cuda.local.array(10, dtype=float64)
    for _zzero58 in range(10):
        floors[_zzero58] = 0.0

    R = int32(0)

    n_stops = int32(0)

    jn = cuda.local.array(18, dtype=float64)
    for _zzero59 in range(18):
        jn[_zzero59] = 0.0

    for d in range(12):

        c = mdi[OI_drive_coord + d]

        jn[c] = float(0.0)

        if abs(q[c] - mdl[OF_lower + c]) < float(1e-10):

            jn[c] = float(1.0)

        elif abs(q[c] - mdl[OF_upper + c]) < float(1e-10):

            jn[c] = float(-1.0)

    for d in range(12):

        c = mdi[OI_drive_coord + d]

        if jn[c] != float(0.0):

            if R >= 10:

                rc[0] = 5

                return float(0.0)

            for i in range(18):

                rows[R * 18 + i] = float(0.0)

            rows[R * 18 + c] = jn[c]

            floors[R] = float(0.0)

            R = R + 1

            n_stops = n_stops + 1

    touching = cuda.local.array(4, dtype=int32)
    for _zzero60 in range(4):
        touching[_zzero60] = 0

    for r in range(4):

        g = gap_of_k(ptp, pt_radius_g, r * 2, cst[CF_plane_y])

        touching[r] = int32(1) if (csti[CI_contact] != 0 and g <= cst[CF_k_touch]) else int32(0)

    rn = cuda.local.array(18, dtype=float64)
    for _zzero61 in range(18):
        rn[_zzero61] = 0.0

    if cst[CF_mu] > float(0.0) and n_stops == 0 and csti[CI_contact] != 0:

        jt1 = cuda.local.array(18, dtype=float64)
        for _zzero62 in range(18):
            jt1[_zzero62] = 0.0

        jt2 = cuda.local.array(18, dtype=float64)
        for _zzero63 in range(18):
            jt2[_zzero63] = 0.0

        row_t = cuda.local.array(18, dtype=float64)
        for _zzero64 in range(18):
            row_t[_zzero64] = 0.0

        force = cuda.local.array(18, dtype=float64)
        for _zzero65 in range(18):
            force[_zzero65] = 0.0

        corr = cuda.local.array(18, dtype=float64)
        for _zzero66 in range(18):
            corr[_zzero66] = 0.0

        ln = cuda.local.array(1, dtype=float64)
        for _zzero67 in range(1):
            ln[_zzero67] = 0.0

        lt = cuda.local.array(1, dtype=float64)
        for _zzero68 in range(1):
            lt[_zzero68] = 0.0

        md = cuda.local.array(1, dtype=int32)
        for _zzero69 in range(1):
            md[_zzero69] = 0

        # CLOSEOUT-4 pair 7: the reference's swallowed-require guards need the
        # pre/post kinetic energies, the mean state, and M-v scratch.
        mv_pre = cuda.local.array(18, dtype=float64)
        for _zzero70b in range(18):
            mv_pre[_zzero70b] = 0.0

        mv_post = cuda.local.array(18, dtype=float64)
        for _zzero70c in range(18):
            mv_post[_zzero70c] = 0.0

        mean_i = cuda.local.array(18, dtype=float64)
        for _zzero70d in range(18):
            mean_i[_zzero70d] = 0.0

        for r in range(4):

            if touching[r] == 0:

                continue

            for i in range(18):

                jt1[i] = ptJ[(r * 3 + 0) * 18 + i]

                jt2[i] = ptJ[(r * 3 + 2) * 18 + i]

                rn[i] = ptJ[(r * 3 + 1) * 18 + i]

            closing = row_dot(rn, v)

            if closing > float(-1e-12):

                continue

            svx = row_dot(jt1, v)

            svz = row_dot(jt2, v)

            planar = math.hypot(svx, svz)

            if planar <= cst[CF_k_slip]:

                continue

            for i in range(18):

                row_t[i] = (svx * jt1[i] + svz * jt2[i]) / planar

            friction_solve(v, inv, rn, row_t, float(0.0), float(0.0), cst[CF_mu], 1, force, ln, lt, md)

            if md[0] > 0:

                mat_vec(inv, force, corr)

                # C++ order: before-energy, mean (from the pre-update v), THEN the

                # v update, post-energy, and the two swallowed requires -- on a

                # require failure the velocity change STAYS but the caught update

                # (and ledger booking) is skipped. Measured at tick 41: r=0's

                # slide catch ln=0.274 failed its gain guard on the reference

                # (caught stayed 0) while the port booked it (caught=0.274) --

                # the Coulomb split then took different intervals.

                mat_vec(M, v, mv_pre)

                before = float(0.5) * row_dot(v, mv_pre)

                for i in range(18):

                    mean_i[i] = v[i] + corr[i] / float(2.0)

                    v[i] = v[i] + corr[i]

                mat_vec(M, v, mv_post)

                loss = before - float(0.5) * row_dot(v, mv_post)

                share_n = ln[0] * row_dot(rn, mean_i)

                share_t = lt[0] * row_dot(row_t, mean_i)

                if loss >= float(-1e-11) and share_n <= float(1e-11) and share_t <= float(1e-11):

                    if ln[0] > caught:

                        caught = ln[0]

    for r in range(4):

        if touching[r] == 0:

            continue

        if R >= 10:

            rc[0] = 5

            return float(0.0)

        for i in range(18):

            rows[R * 18 + i] = ptJ[(r * 3 + 1) * 18 + i]

        floors[R] = float(0.0)

        R = R + 1

    if R > 0:

        p = cuda.local.array(18, dtype=float64)
        for _zzero70 in range(18):
            p[_zzero70] = 0.0

        mult = cuda.local.array(10, dtype=float64)
        for _zzero71 in range(10):
            mult[_zzero71] = 0.0

        if project_rows(v, inv, rows, floors, R, n_stops, p, mult) == 0:

            rc[0] = 5

            return float(0.0)

        corr = cuda.local.array(18, dtype=float64)
        for _zzero72 in range(18):
            corr[_zzero72] = 0.0

        mat_vec(inv, p, corr)

        for i in range(18):

            v[i] = v[i] + corr[i]

    pot = fk_eval(q,  v, mdl, mdi, cst,

                  M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias)

    pen = cuda.local.array(4, dtype=int32)
    for _zzero73 in range(4):
        pen[_zzero73] = 0

    npen = int32(0)

    gaps = cuda.local.array(4, dtype=float64)
    for _zzero74 in range(4):
        gaps[_zzero74] = 0.0

    for r in range(4):

        g = gap_of_k(ptp, pt_radius_g, r * 2, cst[CF_plane_y])

        if csti[CI_contact] != 0 and g < float(-1e-6):

            pen[npen] = r

            gaps[npen] = g

            npen = npen + 1

    if npen > 0:

        gram = cuda.local.array(16, dtype=float64)
        for _zzero75 in range(16):
            gram[_zzero75] = 0.0

        rhs = cuda.local.array(4, dtype=float64)
        for _zzero76 in range(4):
            rhs[_zzero76] = 0.0

        lam = cuda.local.array(4, dtype=float64)
        for _zzero77 in range(4):
            lam[_zzero77] = 0.0

        ra = cuda.local.array(18, dtype=float64)
        for _zzero78 in range(18):
            ra[_zzero78] = 0.0

        ia = cuda.local.array(18, dtype=float64)
        for _zzero79 in range(18):
            ia[_zzero79] = 0.0

        rb = cuda.local.array(18, dtype=float64)

        for _zzero79b in range(18):

            rb[_zzero79b] = 0.0

        wb = cuda.local.array(18, dtype=float64)

        for _zzero79c in range(18):

            wb[_zzero79c] = 0.0

        for a in range(npen):

            for i in range(18):

                ra[i] = ptJ[(pen[a] * 3 + 1) * 18 + i]

            # C++: gram[a*R+b] = inner(arows[a], multiply(inv, arows[b])) -- the

            # ROW_B vector is the one multiplied by inv, and the row_a term leads

            # each product. The old port formed (inv*row_a) first, so every

            # off-diagonal held the TRANSPOSED entry's bits (row_b*inv*row_a):

            # at the tick-41 impact the port's g01/g10 were exactly swapped and

            # the symmetrized gram sent gram_factor4 down a failed pivot.

            for b in range(npen):

                for i in range(18):

                    rb[i] = ptJ[(pen[b] * 3 + 1) * 18 + i]

                mat_vec(inv, rb, wb)

                s = float(0.0)

                for i in range(18):

                    s = s + ra[i] * wb[i]

                # C++ lays the gram out as R*R (stride R == npen): gram[a*R+b].

                # The old port's stride-4 write left cells [2..3] unwritten, so

                # gram_factor4 (which reads stride npen) saw g10=g11=0 and failed

                # the 1e-9 pivot test -- the positional correction was skipped

                # while the reference applied it.

                gram[a * npen + b] = s

            rhs[a] = -gaps[a]

        if gram_factor4(gram, npen, rhs, lam) == 1:

            corr = cuda.local.array(18, dtype=float64)
            for _zzero80 in range(18):
                corr[_zzero80] = 0.0

            for a in range(npen):

                for i in range(18):

                    ra[i] = ptJ[(pen[a] * 3 + 1) * 18 + i]

                mat_vec(inv, ra, ia)

                for i in range(18):

                    corr[i] = corr[i] + lam[a] * ia[i]

            dq_max = float(0.0)

            for i in range(18):

                if abs(corr[i]) > dq_max:

                    dq_max = abs(corr[i])

            if dq_max > float(0.05):

                rc[0] = 3

                return float(0.0)

            for i in range(18):

                q[i] = q[i] + corr[i]

    return caught





# ───────────────────────── the event-driven advance ─────────────────────────

@cuda.jit(device=True, inline='never')

def advance(q0, v0, w0, tau, h, mdl, cst, M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, srq, srv, qa, va, qb, vb, qc, vc, qd, vd, qe, ve, we, sq, sh, sdep, scl, adv, rc, q1, v1, w1, mdi, csti):
    pt_radius_g = mdl[OF_pt_radius:OF_pt_radius + 8]

    # The C++ recursive advance(, mdi, csti) as an explicit LIFO interval stack over the

    # single "current state" thread (q1/v1/w1) -- DFS order preserved.

    for i in range(18):

        q1[i] = q0[i]

        v1[i] = v0[i]

        w1[i] = w0[i]

    if h < float(1e-12):

        return

    sp = int32(0)

    rem = h

    depth = int32(0)

    clamps = int32(0)

    live = cuda.local.array(4, dtype=int32)
    for _zzero81 in range(4):
        live[_zzero81] = 0

    probe = cuda.local.array(4, dtype=int32)
    for _zzero82 in range(4):
        probe[_zzero82] = 0

    it = int32(0)

    done = int32(0)

    rcv = cuda.local.array(1, dtype=int32)
    for _zzero83 in range(1):
        rcv[_zzero83] = 0

    while done == 0:

        it = it + 1

        if it > 4000:

            rc[0] = 6

            return

        if rem < float(1e-12):

            if sp > 0:

                sp = sp - 1

                rem = sh[sp]

                depth = sdep[sp]

                clamps = scl[sp]

                continue

            else:

                done = 1

                break

        adv[0] = adv[0] + 1

        if adv[0] > 3000:

            rc[0] = 2

            return

        if depth >= 10 + 6 * 8:

            rc[0] = 6

            return

        rcv[0] = 0

        caught = impact(q1, v1, mdl, cst, M, gv, bv, fr, frd, frdd,

                        axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, rcv, mdi, csti)

        if rcv[0] != 0:

            rc[0] = rcv[0]

            return

        if cst[CF_mu] > float(0.0) and caught > float(1e-9) and depth < 5:

            sh[sp] = rem * float(0.5)

            sdep[sp] = depth + 3

            scl[sp] = clamps

            sp = sp + 1

            rem = rem * float(0.5)

            depth = depth + 3

            continue

        pot = fk_eval(q1,  v1, mdl, mdi, cst,

                      M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias)

        for r in range(4):

            g = gap_of_k(ptp, pt_radius_g, r * 2, cst[CF_plane_y])

            live[r] = int32(1) if (csti[CI_contact] != 0 and g <= cst[CF_k_touch]) else int32(0)

        rcs = free_step(q1, v1, w1, tau, live, rem, mdl, cst, M, gv, bv, fr, frd, frdd,

                        axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, srq, srv,

                        qa, va, qb, vb, qc, vc, qd, vd, qe, ve, we, mdi, csti)

        if rcs != 0:

            rc[0] = rcs

            return

        # C++ advance holds `end` AS A VALUE: the drive-stop scan, the contact

        # scan, and every localization bisection inside them free_step into

        # temporaries while `end` stays the main interval's result -- the scan

        # pre-test, the per-point re-test, and the plain-end commit all read

        # that saved state. The port's qe/ve/we ARE the shared scratch those

        # bisections overwrite (measured: tick-3 substep-2, the point-4

        # crossing's 42 free_steps left qe/ve at the last mid, so the point-6

        # pre-test read gap +7.0e-7 from the mid state instead of -2.9e-5 from

        # the end state and skipped a landed fore pad). Save the end state and

        # read the copy everywhere the C++ reads `end`.

        end_q = cuda.local.array(18, dtype=float64)

        for _zzeroeq in range(18):

            end_q[_zzeroeq] = 0.0

        end_v = cuda.local.array(18, dtype=float64)

        for _zzeroev in range(18):

            end_v[_zzeroev] = 0.0

        end_w = cuda.local.array(18, dtype=float64)

        for _zzeroew in range(18):

            end_w[_zzeroew] = 0.0

        for i in range(18):

            end_q[i] = qe[i]

            end_v[i] = ve[i]

            end_w[i] = we[i]

        hit = rem

        which = int32(-1)

        khit = int32(-1)

        wall = float(0.0)

        d = int32(0)

        while d < 12:

            d = d + 1

            c = mdi[OI_drive_coord + d - 1]

            low = int32(1) if qe[c] < mdl[OF_lower + c] else int32(0)

            if low == 0 and qe[c] <= mdl[OF_upper + c]:

                continue

            if low != 0:

                depth_v = mdl[OF_lower + c] - qe[c]

            else:

                depth_v = qe[c] - mdl[OF_upper + c]

            if depth_v <= float(1e-12):

                continue

            bound = mdl[OF_lower + c] if low != 0 else mdl[OF_upper + c]

            left = float(0.0)

            right = rem

            j = int32(0)

            while j < 42:

                j = j + 1

                mid = (left + right) * float(0.5)

                rcb = free_step(q1, v1, w1, tau, live, mid, mdl, cst, M, gv, bv, fr, frd, frdd,

                                axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, srq, srv,

                                qa, va, qb, vb, qc, vc, qd, vd, qe, ve, we, mdi, csti)

                if rcb != 0:

                    rc[0] = rcb

                    return

                if low != 0:

                    ok2 = int32(1) if qe[c] <= bound else int32(0)

                else:

                    ok2 = int32(1) if qe[c] >= bound else int32(0)

                if ok2 != 0:

                    right = mid

                else:

                    left = mid

            t = (left + right) * float(0.5)

            if t < hit or (t == hit and which >= 0 and (d - 1) < which):

                hit = t

                which = d - 1

                khit = -1

                wall = bound

        if csti[CI_contact] != 0:

            pot = fk_eval(end_q,  end_v, mdl, mdi, cst,

                          M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias)

            r = int32(0)

            while r < 4:

            # (while-form of the rep scan; body below)

                r = r + 1

                if live[r - 1] != 0:

                    continue

                # C++ holds eend=evaluate(end) from BEFORE the scan loop and tests

                # gap_of(eend,k) per point. The port's ptp AND qe/ve scratch are

                # shared with free_step, so an earlier point's bisection leaves

                # them at the last mid -- the per-point tests re-evaluate the

                # SAVED end state (same bits: same inputs, same fk_eval).

                pot = fk_eval(end_q,  end_v, mdl, mdi, cst,

                              M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias)

                g = gap_of_k(ptp, pt_radius_g, (r - 1) * 2, cst[CF_plane_y])

                if g >= float(0.0):

                    continue

                for rr in range(4):

                    probe[rr] = live[rr]

                probe[r - 1] = 0

                left = float(0.0)

                right = rem

                j = int32(0)

                while j < 42:

                    j = j + 1

                    mid = (left + right) * float(0.5)

                    rcb = free_step(q1, v1, w1, tau, probe, mid, mdl, cst, M, gv, bv, fr, frd, frdd,

                                    axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, srq, srv,

                                    qa, va, qb, vb, qc, vc, qd, vd, qe, ve, we, mdi, csti)

                    if rcb != 0:

                        rc[0] = rcb

                        return

                    # C++: gap_of(evaluate(free_step(start,mid,tau,probe)),k) -- the gap

                    # test runs on the free_step's END state. Without this evaluate the

                    # test read ptp left by the last fk_eval INSIDE free_step -- the

                    # stage-d RK intermediate (qd,vd), not the combine (qe,ve) -- and the

                    # crossing-time bisection took the opposite branch whenever the two

                    # gaps straddled 0 (measured: tick-3 substep-2, fore-pad landing,

                    # one branch flip at bisection iteration 31; the free_step end bits

                    # themselves were identical on both sides).

                    pot = fk_eval(qe,  ve, mdl, mdi, cst,

                                  M, gv, bv, fr, frd, frdd, axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias)

                    if gap_of_k(ptp, pt_radius_g, (r - 1) * 2, cst[CF_plane_y]) <= float(0.0):

                        right = mid

                    else:

                        left = mid

                t = (left + right) * float(0.5)

                if t < hit:

                    hit = t

                    which = -2

                    khit = r - 1

                r = r

        if which == -1:

            for i in range(18):

                q1[i] = end_q[i]

                v1[i] = end_v[i]

                w1[i] = end_w[i]

            if sp > 0:

                sp = sp - 1

                rem = sh[sp]

                depth = sdep[sp]

                clamps = scl[sp]

                continue

            else:

                done = 1

                break

        if hit <= float(1e-12):

            if clamps >= 64:

                rc[0] = 6

                return

            if which >= 0:

                q1[mdi[OI_drive_coord + which]] = wall

            rcv[0] = 0

            caught = impact(q1, v1, mdl, cst, M, gv, bv, fr, frd, frdd,

                            axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, rcv, mdi, csti)

            if rcv[0] != 0:

                rc[0] = rcv[0]

                return

            clamps = clamps + 1

            continue

        if which == -2:

            for rr in range(4):

                probe[rr] = live[rr]

            probe[khit] = 0

            rcc = free_step(q1, v1, w1, tau, probe, hit, mdl, cst, M, gv, bv, fr, frd, frdd,

                            axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, srq, srv,

                            qa, va, qb, vb, qc, vc, qd, vd, qe, ve, we, mdi, csti)

            if rcc != 0:

                rc[0] = rcc

                return

            for i in range(18):

                q1[i] = qe[i]

                v1[i] = ve[i]

                w1[i] = we[i]

            rcv[0] = 0

            caught = impact(q1, v1, mdl, cst, M, gv, bv, fr, frd, frdd,

                            axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, rcv, mdi, csti)

            if rcv[0] != 0:

                rc[0] = rcv[0]

                return

            if cst[CF_mu] > float(0.0):

                sh[sp] = (rem - hit) * float(0.5)

                sdep[sp] = depth + 2

                scl[sp] = clamps

                sp = sp + 1

                rem = (rem - hit) * float(0.5)

                depth = depth + 1

            else:

                rem = rem - hit

                depth = depth + 1

            continue

        rcw = free_step(q1, v1, w1, tau, live, hit, mdl, cst, M, gv, bv, fr, frd, frdd,

                        axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, srq, srv,

                        qa, va, qb, vb, qc, vc, qd, vd, qe, ve, we, mdi, csti)

        if rcw != 0:

            rc[0] = rcw

            return

        for i in range(18):

            q1[i] = qe[i]

            v1[i] = ve[i]

            w1[i] = we[i]

        q1[mdi[OI_drive_coord + which]] = wall

        rcv[0] = 0

        caught = impact(q1, v1, mdl, cst, M, gv, bv, fr, frd, frdd,

                        axw, axpiv, axdir, ptp, ptJ, ptcop, ptbias, inv, free, rcv, mdi, csti)

        if rcv[0] != 0:

            rc[0] = rcv[0]

            return

        rem = rem - hit

        depth = depth + 1

        continue





# ───────────────────────── the closed-form IK helpers ─────────────────────────

@cuda.jit(device=True)

def fore_ik_at(mdl, cst, fr, leg, paw, branch, mdi, csti):

    off = csti[CI_pelvis_row] * 16

    rx = paw[0] - fr[off + 3]

    ry = paw[1] - fr[off + 7]

    rz = paw[2] - fr[off + 11]

    ml0 = mdl[OF_fore_mount_local + leg * 3]

    ml1 = mdl[OF_fore_mount_local + leg * 3 + 1]

    dx = fr[off + 0] * rx + fr[off + 4] * ry + fr[off + 8] * rz - ml0

    dy = fr[off + 1] * rx + fr[off + 5] * ry + fr[off + 9] * rz - ml1

    D = math.hypot(dx, dy)  # C++ std::hypot(dx,dy) (fore_ik_at)

    dmax = cst[CF_fore_L1] + cst[CF_fore_rho]

    dmin = abs(cst[CF_fore_L1] - cst[CF_fore_rho])

    sat = int32(0)

    # PREREG REACH BAND v1 (Astra Option A, registered 2026-09-23): the
    # boundary treatment is a versioned numerical policy. The registered band
    # is [dmax*(1-1e-9), dmax] (one-sided, closed; D>dmax stays genuinely
    # infeasible). In-band D snaps to the single canonical boundary value
    # dcan; outside the band the legacy bytes are EXACT (outside-band drift 0).
    dcan = dmax * (float(1.0) - float(1e-9))

    if D > dmax or D >= dcan or D < dmin + float(1e-9):

        sat = 1

        if D > dmax:

            Dc = dmax * (float(1.0) - float(1e-12))

        elif D >= dcan:

            Dc = dcan

        else:

            Dc = min(max(D, dmin + float(1e-9)), dmax * (float(1.0) - float(1e-12)))

        dx = dx * Dc / D

        dy = dy * Dc / D

        D = Dc

    ca = (D * D + cst[CF_fore_L1] * cst[CF_fore_L1] - cst[CF_fore_rho] * cst[CF_fore_rho]) / (float(2.0) * D * cst[CF_fore_L1])

    ca = min(float(1.0), max(float(-1.0), ca))

    th1 = math.atan2(dy, dx) + float(branch) * math.acos(ca)

    q1 = th1 + PI * float(0.5)

    ex = dx - cst[CF_fore_L1] * math.cos(th1)

    ey = dy - cst[CF_fore_L1] * math.sin(th1)

    q2 = math.atan2(ey, ex) - q1 - cst[CF_fore_beta]

    c1 = mdi[OI_fore_coord + leg * 2]

    c2 = mdi[OI_fore_coord + leg * 2 + 1]

    q1r = q1

    q2r = q2

    q1 = min(mdl[OF_upper + c1], max(mdl[OF_lower + c1], q1))

    q2 = min(mdl[OF_upper + c2], max(mdl[OF_lower + c2], q2))

    return q1, q2, q1r, q2r, sat





@cuda.jit(device=True)

def fore_D_at(mdl, cst, fr, leg, paw, csti):

    off = csti[CI_pelvis_row] * 16

    rx = paw[0] - fr[off + 3]

    ry = paw[1] - fr[off + 7]

    rz = paw[2] - fr[off + 11]

    ml0 = mdl[OF_fore_mount_local + leg * 3]

    ml1 = mdl[OF_fore_mount_local + leg * 3 + 1]

    dx = fr[off + 0] * rx + fr[off + 4] * ry + fr[off + 8] * rz - ml0

    dy = fr[off + 1] * rx + fr[off + 5] * ry + fr[off + 9] * rz - ml1

    return math.hypot(dx, dy)  # C++ std::hypot (fore_D_at)





@cuda.jit(device=True)

def hind_ik_at(mdl, cst, fr, tgt, ap, branch, csti):

    off = csti[CI_pelvis_row] * 16

    rx = tgt[0] - fr[off + 3]

    ry = tgt[1] - fr[off + 7]

    rz = tgt[2] - fr[off + 11]

    dx = fr[off + 0] * rx + fr[off + 4] * ry + fr[off + 8] * rz

    dy = fr[off + 1] * rx + fr[off + 5] * ry + fr[off + 9] * rz

    wx = dx - cst[CF_hind_xm] * math.cos(ap)

    wy = dy - cst[CF_hind_xm] * math.sin(ap)

    D = math.hypot(wx, wy)  # C++ std::hypot (hind_ik_at)

    dmax = cst[CF_hind_L1] + cst[CF_hind_L2]

    dmin = abs(cst[CF_hind_L1] - cst[CF_hind_L2])

    Dc = min(max(D, dmin + float(1e-9)), dmax * (float(1.0) - float(1e-12)))

    ca = (Dc * Dc - cst[CF_hind_L1] * cst[CF_hind_L1] - cst[CF_hind_L2] * cst[CF_hind_L2]) / (float(2.0) * cst[CF_hind_L1] * cst[CF_hind_L2])

    ca = min(float(1.0), max(float(-1.0), ca))

    k = float(branch) * math.acos(ca)

    a1 = math.atan2(wy, wx) - math.atan2(-cst[CF_hind_L1] - cst[CF_hind_L2] * math.cos(k), cst[CF_hind_L2] * math.sin(k))

    qh = a1

    qk = k

    qa = ap - a1 - k

    return qh, qk, qa





@cuda.jit(device=True)

def tables_at(mdl, phi, out):


    p = phi - math.floor(phi)

    x = p * float(20.0)

    k = int32(x)

    if k > 19:

        k = 19

    f = x - float(k)

    out[0] = mdl[OF_tab_hip + k] * (float(1.0) - f) + mdl[OF_tab_hip + k + 1] * f + mdl[OF_zeros4 + 0]

    out[1] = mdl[OF_tab_knee + k] * (float(1.0) - f) + mdl[OF_tab_knee + k + 1] * f + mdl[OF_zeros4 + 1]

    out[2] = mdl[OF_tab_ankle + k] * (float(1.0) - f) + mdl[OF_tab_ankle + k + 1] * f + mdl[OF_zeros4 + 2]

    out[3] = mdl[OF_tab_mp + k] * (float(1.0) - f) + mdl[OF_tab_mp + k + 1] * f + mdl[OF_zeros4 + 3]

    return out





@cuda.jit(device=True)

def vault_at(mdl, phi):

    p = phi - math.floor(phi)

    x = p * float(20.0)

    k = int32(x)

    if k > 19:

        k = 19

    f = x - float(k)

    return mdl[OF_vault + k] * (float(1.0) - f) + mdl[OF_vault + k + 1] * f



