@cuda.jit(device=True)

def fore_target_headroom(mdl, cst, fr, leg, paw, branch, mdi, csti):

    d1a, d1b, q1r, q2r, d1c = fore_ik_at(mdl, cst, fr, leg, paw, branch, mdi, csti)

    c1 = mdi[OI_fore_coord + leg * 2]

    c2 = mdi[OI_fore_coord + leg * 2 + 1]

    h1 = min(q1r - mdl[OF_lower + c1], mdl[OF_upper + c1] - q1r)

    h2 = min(q2r - mdl[OF_lower + c2], mdl[OF_upper + c2] - q2r)

    return min(h1, h2)





@cuda.jit(device=True)

def fore_follow(mdl, cst, fr, leg, paw_t, branch, mdi, csti, result):

    p = cuda.local.array(3, dtype=float64)
    for _zzero84 in range(3):
        p[_zzero84] = 0.0

    p[0] = paw_t[leg * 3]

    p[1] = paw_t[leg * 3 + 1]

    p[2] = paw_t[leg * 3 + 2]

    px = cuda.local.array(3, dtype=float64)
    for _zzero85 in range(3):
        px[_zzero85] = 0.0

    py = cuda.local.array(3, dtype=float64)
    for _zzero86 in range(3):
        py[_zzero86] = 0.0

    px[0] = p[0] + float(1e-3)

    px[1] = p[1]

    px[2] = p[2]

    py[0] = p[0] - float(1e-3)

    py[1] = p[1]

    py[2] = p[2]

    dirn = float(1.0)

    if fore_target_headroom(mdl, cst, fr, leg, px, branch, mdi, csti) < fore_target_headroom(mdl, cst, fr, leg, py, branch, mdi, csti):

        dirn = float(-1.0)

    dmax = cst[CF_fore_L1] + cst[CF_fore_rho]

    lo = float(0.0)

    hi = float(2.0) * dmax

    for j in range(42):

        mid = (lo + hi) * float(0.5)

        t = cuda.local.array(3, dtype=float64)
        for _zzero87 in range(3):
            t[_zzero87] = 0.0

        t[0] = p[0] + dirn * mid

        t[1] = p[1]

        t[2] = p[2]

        if fore_D_at(mdl, cst, fr, leg, t, csti) < dmax:

            lo = mid

        else:

            hi = mid

    edge = (lo + hi) * float(0.5)

    te = cuda.local.array(3, dtype=float64)
    for _zzero88 in range(3):
        te[_zzero88] = 0.0

    te[0] = p[0] + dirn * edge

    te[1] = p[1]

    te[2] = p[2]

    if fore_target_headroom(mdl, cst, fr, leg, te, branch, mdi, csti) < float(0.1022):

        result[0] = te[0]
        result[1] = te[1]
        result[2] = te[2]
        return result

    lo = float(0.0)

    hi = edge

    for j in range(42):

        mid = (lo + hi) * float(0.5)

        t = cuda.local.array(3, dtype=float64)
        for _zzero89 in range(3):
            t[_zzero89] = 0.0

        t[0] = p[0] + dirn * mid

        t[1] = p[1]

        t[2] = p[2]

        if fore_target_headroom(mdl, cst, fr, leg, t, branch, mdi, csti) < float(0.1022):

            lo = mid

        else:

            hi = mid

    out = cuda.local.array(3, dtype=float64)
    for _zzero90 in range(3):
        out[_zzero90] = 0.0

    out[0] = p[0] + dirn * ((lo + hi) * float(0.5))

    out[1] = p[1]

    out[2] = p[2]

    result[0] = out[0]
    result[1] = out[1]
    result[2] = out[2]
    return result





@cuda.jit(device=True)

def fore_arm_hold(mdl, cst, fr, leg, wall_bound, f_t, f_st, f_cy, paw_t, swf, swt, ikb, mdi, csti, f_hgh, f_hhl, f_hoff):
    # CLOSEOUT-8: THE POCKET-CLEAR HOLD (wave 24) ported -- the DEFERRED-W24
    # deferral turned load-bearing at tick 73 (the no-double-swing gate's
    # clause (a) exempts a held glide, and the held glide's target is the
    # body-locked annulus-edge seat). Mirror of fore_glide_arm_hold
    # (gait_controller_ref.hpp:1008) -- same 42-step dmax bisection (fore_D_at),
    # same per-tick line march through fore_ik_at (the branch the leg stored),
    # same held span [1, last] with last = the final out-of-range march tick.
    f_hgh[leg] = 0

    f_hhl[leg] = 0

    if wall_bound == 0:

        return

    n = int(f_cy[leg] - f_st[leg])

    if n < 2:

        return

    m16 = cuda.local.array(16, dtype=float64)
    for _coh1 in range(16):
        m16[_coh1] = 0.0

    for i in range(16):

        m16[i] = fr[csti[CI_pelvis_row] * 16 + i]

    shw = cuda.local.array(3, dtype=float64)
    for _coh2 in range(3):
        shw[_coh2] = 0.0

    ml = cuda.local.array(3, dtype=float64)
    for _coh3 in range(3):
        ml[_coh3] = 0.0

    ml[0] = mdl[OF_fore_mount_local + leg * 3]

    ml[1] = mdl[OF_fore_mount_local + leg * 3 + 1]

    ml[2] = mdl[OF_fore_mount_local + leg * 3 + 2]

    vec_point(m16, ml, shw)

    px = cuda.local.array(3, dtype=float64)
    py = cuda.local.array(3, dtype=float64)
    t = cuda.local.array(3, dtype=float64)
    for _coh4 in range(3):
        px[_coh4] = 0.0
        py[_coh4] = 0.0
        t[_coh4] = 0.0

    px[0] = paw_t[leg * 3] + float(1e-3)

    px[1] = paw_t[leg * 3 + 1]

    px[2] = paw_t[leg * 3 + 2]

    py[0] = paw_t[leg * 3] - float(1e-3)

    py[1] = paw_t[leg * 3 + 1]

    py[2] = paw_t[leg * 3 + 2]

    dr = float(-1.0)

    if fore_target_headroom(mdl, cst, fr, leg, px, ikb[leg], mdi, csti) >= fore_target_headroom(mdl, cst, fr, leg, py, ikb[leg], mdi, csti):

        dr = float(1.0)

    dmax = cst[CF_fore_L1] + cst[CF_fore_rho]

    lo = float(0.0)

    hi = float(2.0) * dmax

    for j in range(42):

        mid = (lo + hi) / float(2.0)

        t[0] = paw_t[leg * 3] + dr * mid

        t[1] = paw_t[leg * 3 + 1]

        t[2] = paw_t[leg * 3 + 2]

        if fore_D_at(mdl, cst, fr, leg, t, csti) < dmax:

            lo = mid

        else:

            hi = mid

    f_hoff[leg * 3] = paw_t[leg * 3] + dr * ((lo + hi) / float(2.0)) - shw[0]

    f_hoff[leg * 3 + 1] = paw_t[leg * 3 + 1] - shw[1]

    f_hoff[leg * 3 + 2] = paw_t[leg * 3 + 2] - shw[2]

    c1 = mdi[OI_fore_coord + leg * 2]

    c2 = mdi[OI_fore_coord + leg * 2 + 1]

    last = 0

    for k in range(1, n + 1):

        sg = float(k) / float(n)

        t[0] = swf[leg * 3] + (swt[leg * 3] - swf[leg * 3]) * sg

        t[1] = swf[leg * 3 + 1] + (swt[leg * 3 + 1] - swf[leg * 3 + 1]) * sg

        t[2] = swf[leg * 3 + 2] + (swt[leg * 3 + 2] - swf[leg * 3 + 2]) * sg

        dq1, dq2, q1r, q2r, dsat = fore_ik_at(mdl, cst, fr, leg, t, ikb[leg], mdi, csti)

        if q1r < mdl[OF_lower + c1] or q1r > mdl[OF_upper + c1] or q2r < mdl[OF_lower + c2] or q2r > mdl[OF_upper + c2]:

            last = k

    if last > 0:

        f_hgh[leg] = 1

        f_hhl[leg] = last

    return





@cuda.jit(device=True)

def fore_env(mdl, cst, fr, leg, paw_t, v3, csti, paw_plant_y):
    # CLOSEOUT-8 TICK-66 FIX: the reach envelope is measured at the PLANT
    # HEIGHT (the captured settle reference y -- the C++ paw_plant_y_[leg]
    # read inside fore_amax, gait_controller_ref.hpp:1096), not at the live
    # paw-TARGET y. The target's y rides the swing clearance arch (up to
    # 2*pad-radius above the plant line), which shrank hgt, grew amax, and
    # grew tau_env by ~2.6 ticks at the tick-66 fore-right state (cpp
    # envt 5.854 vs host >7): the wave-20 envelope-edge re-plant
    # (f_t >= env_t) never fired on the translated side, the glide kept its
    # stale schedule, and the fore-right servo targets split O(0.09) -- the
    # tick-66 discrete flip. The Warp original has the same paw_t[leg*3+1]
    # read; the C++ reference is the parity target (the closeout-6
    # vec_point precedent).

    m16 = cuda.local.array(16, dtype=float64)
    for _zzero91 in range(16):
        m16[_zzero91] = 0.0

    for i in range(16):

        m16[i] = fr[csti[CI_pelvis_row] * 16 + i]

    shw = cuda.local.array(3, dtype=float64)
    for _zzero92 in range(3):
        shw[_zzero92] = 0.0

    ml = cuda.local.array(3, dtype=float64)
    for _zzero93 in range(3):
        ml[_zzero93] = 0.0

    ml[0] = mdl[OF_fore_mount_local + leg * 3]

    ml[1] = mdl[OF_fore_mount_local + leg * 3 + 1]

    ml[2] = mdl[OF_fore_mount_local + leg * 3 + 2]

    vec_point(m16, ml, shw)

    off = paw_t[leg * 3] - shw[0]

    hgt = max(float(0.0), shw[1] - paw_plant_y)

    dd = cst[CF_fore_L1] + cst[CF_fore_rho]

    a2 = dd * dd - hgt * hgt

    amax = math.sqrt(a2) if a2 > float(0.0) else float(0.0)

    vv = max(float(0.0), v3)

    if vv <= float(1e-9):

        return float(0.0)

    env_s = (amax + off - vv * cst[CF_dt]) / vv / cst[CF_dt]

    if env_s < float(0.0):

        env_s = float(0.0)

    return env_s





@cuda.jit(device=True)

def hind_deadline_fn(h_lt_o, h_lt_h, tair, fold_budget, unload_ticks):

    # returns (deadline_tick, is_unload); 0 deadline = no completed other step

    dl = np.int64(0)

    is_unload = int32(0)

    if h_lt_o == np.int64(0):

        return dl, is_unload

    fold = h_lt_o + np.int64(fold_budget - tair - 1)

    dl = fold

    if h_lt_h != np.int64(0):

        unload = h_lt_o + np.int64(unload_ticks - 1)

        if unload < fold:

            dl = unload

            is_unload = 1

    return dl, is_unload





